from csv import reader
from typing import Dict, List, Tuple, Union


class MissingFieldError(Exception):
    """Exception raised when field name is not found in list."""
    pass


# TODO: record i/lub Filter iterator na self.new_data -> __iter__()
class Filters(object):
    """Filter methods for tti trace."""
    def __init__(self, **kwargs):
        # type: (Dict[str, Union[str, List[str], List[List[str]]]]) -> None
        """
        Dynamic initialization.
        :param csv_table: list with full trace data
        :param header: trace header
        :param fields: data with fields of trave
        :param current_table: filtered ttace data
        """
        if 'csv_table' in kwargs:
            self.csv_table = kwargs['csv_table']
        if 'header' in kwargs:
            self.header = kwargs['header']
        if 'fields' in kwargs:
            self.fields = kwargs['fields']
        if 'current_table' in kwargs:
            self.current_table = kwargs['current_table']

    def __repr__(self):
        # type: () -> str
        """Show info how to get results."""
        return "To get results add 'result_list' to filter method,\n" \
               "eg.: trace.rows_with_pattern(field, pattern).result_list"

    def __len__(self):
        # type: () -> int
        return len(self.current_table)

    def __add__(self, other):
        # type: (Filters) -> Filters
        self.current_table += other.current_table
        return self

    def __iadd__(self, other):
        # type: (Filters) -> Filters
        self.current_table += other.current_table
        return self

    @property
    def result_list(self):
        # type: () -> List[str]
        """Return current data."""
        return self.current_table

    def rows_with_pattern(self, field, pattern):
        # type: (str, str) -> Filters
        """Return rows where values matches pattern in given field."""
        result = []
        pattern = str(pattern)
        position = self._get_field_position(field)
        print('Size of lookup table {} rows.'.format(len(self)))
        for row in self.current_table:
            if pattern == row[position]:
                result.append(row)
        print('{} rows for field {} at index {} with matching pattern {}'.format(len(result), field, position, pattern))
        return Filters(current_table=result, fields=self.fields, header=self.header)

    def rows_without_pattern(self, field, pattern):
        # type: (str, str) -> Filters
        """
        Return rows not containing specified value in field.
        :param field:
        :param pattern:
        """
        result = []
        pattern = str(pattern)
        position = self._get_field_position(field)
        for row in self.current_table:
            if pattern != row[position]:
                result.append(row)
        return Filters(current_table=result, fields=self.fields, header=self.header)

    # TODO: maybe return list (do not need result_list at all) because calling any other filter on v_by_f is pointless now
    def values_by_field(self, field, unique=False):
        # type: (str, bool) -> Filters
        """
        Return list of filtered values fetched from selected field.
        :param field: field name
        :param unique: return set instead of repeated values
        """
        result = []
        position = self._get_field_position(field)
        for row in self.current_table:
            result.append(row[position])
        if unique:
            result = list(set(result))
        return Filters(current_table=result, fields=self.fields, header=self.header)

    def ue(self, crnti=''):
        # type: (Union[int, str, List[Union[int, str]]]) -> Filters
        """
        Return rows for all or specified Ues.
        :param crnti: UE Cell Radio Network Temporary Identifier
        """
        inf = 'Requested data for UE with CRNTI: {}'
        ue_crnti_field = self._get_ue_crnti_fieldname()
        if crnti:
            if not isinstance(crnti, list):
                crnti = [crnti]
            result = self.rows_with_pattern(ue_crnti_field, str(crnti[0]))
            print(inf.format(crnti[0]))
            for ue in crnti[1:]:
                result += self.rows_with_pattern(ue_crnti_field, str(ue))
                print(inf.format(ue))
            return result

        print('Requested data for all UEs.')
        return self.rows_without_pattern(ue_crnti_field, '-')

    def cell(self, cell_id=''):
        # type: (Union[int, str, List[Union[int, str]]]) -> Filters
        """
        Return rows for all or specific cells.
        :param cell_id: LNCEL id
        """
        _, direction = self.trace_type()
        field_pattern = 'ETtiTrace{}ParCell_cellId'

        if cell_id:
            if not isinstance(cell_id, list):
                cell_id = [cell_id]
            print('Requested data for LNCEL-{}'.format(cell_id[0]))
            return self.rows_with_pattern(field_pattern.format(direction), str(cell_id[0]))

        print('Requested data for all LNCELs')
        # Return all rows, because cell is always present in trace
        return self

    def trace_type(self):
        # type: () -> Tuple[str, str]
        """
        Returns used UE technology (TDD/FDD) and direction (DL/UL).
        :return pair of (technology, direction)
        """
        type_mapping = {'DL_WMP': ('FDD', 'Dl'), 'UL_WMP': ('FDD', 'Ul'),
                        'DL_high': ('TDD', 'Dl'), 'UL_high': ('TDD', 'Ul')}
        return type_mapping[self.header[4]]

    def _get_field_position(self, field):
        try:
            return self.fields.index(field)
        except ValueError:
            raise MissingFieldError('Field {} not found in list.\n'
                                    'Possible wrong trace type assumption FDD/TDD or typo.'.format(field))

    def _get_ue_crnti_fieldname(self):
        # type: () -> str
        """
        Return correct Cell Radio Network Temporary Identifier field name for UE.
        TDD: ETtiTrace{}ParUe_crnti
        FDD: ETtiTrace{}ParUe_cRnti
        """
        tech, direction = self.trace_type()
        field_pattern = 'ETtiTrace{}ParUe_cRnti'
        if tech == 'TDD':
            field_pattern = 'ETtiTrace{}ParUe_crnti'
        ue_field_name = field_pattern.format(direction)
        return ue_field_name


class Trace(Filters):
    """Store traces in its heart"""
    def __init__(self, **kwargs):
        # type: (Dict[str, str]) -> None
        """
        Initialize trace from file name.
        :param filename: full path to parsed text tti traces
        """
        if kwargs['filename']:
            self.filename = kwargs['filename']
            with open(self.filename, 'r') as trace:
                res = reader(trace, dialect='excel', delimiter=',')
                _csv = list(res)
            self.header = _csv[0]
            self.fields = _csv[1]
            self.csv_table = _csv[2:]
            super(Trace, self).__init__(current_table=self.csv_table, fields=self.fields,
                                        header=self.header, csv_table=self.csv_table)
        else:
            # todo: maybe add logger
            raise ValueError('Trace not initialized, missing "filename" parameter')

    def __str__(self):
        # type: () -> str
        """Show info, about which file was used for parsing."""
        return 'Using file: {}'.format(self.filename)

    def __len__(self):
        # type: () -> int
        return len(self.csv_table)
